/* Banco de questões. a: pato | imuno | int ; t: temas ; c: índice da correta */
window.QUESTIONS = [
/* ======================= PATOLOGIA ======================= */
{id:"p1",a:"pato",t:["p-autoimune"],s:"Durante a maturação no timo, um linfócito T reconhece com alta afinidade um peptídeo de insulina apresentado graças à expressão do gene AIRE. Qual o destino esperado desse linfócito e qual mecanismo está envolvido?",
o:["Anergia, por ausência de coestimulação — tolerância periférica","Apoptose por seleção negativa — tolerância central","Edição de receptor — tolerância central","Supressão por Treg — tolerância periférica","Diferenciação em Treg obrigatória — tolerância periférica"],c:1,
e:"No timo (órgão linfoide primário) o T com alta afinidade pelo self sofre <b>seleção negativa → apoptose</b> = tolerância central. O AIRE permite que antígenos de tecidos periféricos (como insulina) sejam expressos no timo. Edição de receptor é mecanismo do <b>linfócito B</b> na medula. Anergia e Treg são periféricos."},
{id:"p2",a:"pato",t:["p-autoimune"],s:"Menino de 10 anos desenvolve cardite e poliartrite 3 semanas após faringite estreptocócica. Anticorpos contra a proteína M do estreptococo reagem com proteínas do miocárdio. Qual mecanismo de quebra de tolerância está ilustrado?",
o:["Ativação bystander","Exposição de antígenos sequestrados por trauma","Mimetismo molecular","Defeito monogênico de FOXP3","Espalhamento de epítopos primário"],c:2,
e:"Antígeno microbiano quase idêntico a uma proteína própria = <b>mimetismo molecular</b> — exemplo clássico da aula: <b>febre reumática</b>. Bystander seria ativação inespecífica por inflamação aumentando coestimulação."},
{id:"p3",a:"pato",t:["p-autoimune"],s:"Sobre o caráter crônico e com surtos das doenças autoimunes, assinale a explicação correta:",
o:["Os autoantígenos são eliminados após o primeiro surto, e a doença recidiva por nova exposição","A lesão tecidual expõe novos autoantígenos que ativam outros linfócitos autorreativos (espalhamento de epítopos)","As doenças autoimunes são sempre órgão-específicas, o que limita a resposta","Linfócitos autorreativos entram em anergia definitiva após o primeiro surto","A cronicidade se deve exclusivamente à predisposição HLA"],c:1,
e:"Autoantígeno é persistente (é próprio) e a lesão libera antígenos escondidos que ativam novos clones: <b>espalhamento de epítopos</b> → feedback positivo → recidivas e remissões."},
{id:"p4",a:"pato",t:["p-les"],s:"Mulher, 26 anos, com eritema malar que piora ao sol, artralgias, edema de membros inferiores e proteinúria. Biópsia renal mostra espessamento circunferencial da parede capilar glomerular por depósitos subendoteliais. Qual o achado descrito e o mecanismo de lesão?",
o:["Crescentes glomerulares — hipersensibilidade tipo II","Alça de arame (wire loop) — hipersensibilidade tipo III","Lesão em casca de cebola — hipersensibilidade tipo IV Th2","Nódulos de Kimmelstiel-Wilson — tipo IV","Necrose tubular aguda — hipoperfusão"],c:1,
e:"Depósito maciço <b>subendotelial</b> de imunocomplexos → espessamento circunferencial = <b>alça de arame</b>, na glomerulonefrite proliferativa difusa do LES, mediada por <b>tipo III</b>. Casca de cebola é da esclerodermia (vasos)."},
{id:"p5",a:"pato",t:["p-les"],s:"Na histologia da pele de uma paciente lúpica com eritema em asa de borboleta, espera-se encontrar:",
o:["Acantose e paraceratose com microabscessos de Munro","Degeneração vacuolar das células basais na junção dermoepidérmica","Derme substituída por colágeno denso hialinizado e perda de anexos","Granuloma com necrose caseosa","Bolha subepidérmica por anticorpos anti-hemidesmossomo"],c:1,
e:"Achado da aula: <b>degeneração vacuolar da camada basal</b> na junção dermoepidérmica. Colágeno hialinizado com perda de anexos é a pele da <b>esclerodermia</b>."},
{id:"p6",a:"pato",t:["p-les"],s:"Nas vasculites do LES, o material eosinofílico amorfo encontrado na parede de arteríolas, produto da destruição inflamatória, é chamado de:",
o:["Hialinose","Necrose fibrinoide","Necrose caseosa","Amiloide","Necrose liquefativa"],c:1,
e:"Vasculite necrotizante aguda com <b>necrose fibrinoide</b>; na fase crônica há espessamento fibroso e estreitamento da luz."},
{id:"p7",a:"pato",t:["p-ar"],s:"Paciente com artrite reumatoide de longa data apresenta nódulos firmes e indolores na face extensora do antebraço. A biópsia mostrará:",
o:["Necrose fibrinoide central circundada por macrófagos em paliçada, linfócitos e plasmócitos","Tofos de urato com reação de corpo estranho","Granuloma com necrose caseosa e células de Langhans","Proliferação fibroblástica sem inflamação","Depósito de amiloide com birrefringência verde-maçã"],c:0,
e:"Nódulo reumatoide = parece <b>granuloma necrosante</b>: necrose fibrinoide central + <b>macrófagos em paliçada</b> + linfócitos e plasmócitos. Ocorre em áreas de atrito (antebraço, cotovelo, occipital, lombossacral)."},
{id:"p8",a:"pato",t:["p-ar"],s:"Sobre o pannus da artrite reumatoide, é INCORRETO afirmar:",
o:["É formado por sinóvia hiperplásica, infiltrado inflamatório e angiogênese","Pode haver exsudato fibrinopurulento nas superfícies articulares","A atividade osteoclástica no osso subcondral produz erosões e cistos","Após destruir a cartilagem, pode levar a anquilose fibrosa e depois óssea","É composto essencialmente por depósitos de imunocomplexos acelulares, sem participação de células T"],c:4,
e:"O pannus é tecido <b>celular</b>: sinoviócitos proliferados, T CD4, B, dendríticas, macrófagos, vasos novos. A AR mistura tipo III <b>e tipo IV</b>."},
{id:"p9",a:"pato",t:["p-ar"],s:"Mulher tabagista de 45 anos com poliartrite simétrica das mãos. Qual autoanticorpo é mais específico para o diagnóstico?",
o:["Fator reumatoide","FAN","Anti-CCP","Anti-dsDNA","Anticentrômero"],c:2,
e:"<b>Anti-CCP</b> (antipeptídeo citrulinado) é específico da AR. O fator reumatoide (IgM anti-IgG) não é específico. O tabagismo induz citrulinação no pulmão."},
{id:"p10",a:"pato",t:["p-sjogren-esclero"],s:"Mulher de 50 anos com olhos e boca secos há 2 anos e aumento de parótidas. Biópsia de glândula salivar menor mostra infiltrado linfocítico com folículos ectópicos, destruição de ácinos e ilhotas epimioepiteliais. Qual complicação deve ser monitorada?",
o:["Carcinoma espinocelular de boca","Linfoma de células B","Fibrose pulmonar como principal causa de morte","Crise renal hipertensiva","Esôfago de Barrett"],c:1,
e:"Síndrome de Sjögren: estímulo crônico de B → <b>risco até 40× de linfoma B</b>. Fibrose pulmonar e crise renal são da esclerodermia."},
{id:"p11",a:"pato",t:["p-sjogren-esclero"],s:"Na esclerose sistêmica, qual sequência explica a fibrose?",
o:["Th1 → IFN-γ → macrófago M1 → destruição tecidual","Th2 → IL-4/IL-13 → macrófago M2 → TGF-β → miofibroblastos → colágeno","Th17 → IL-17 → neutrófilos → necrose fibrinoide","IgE → mastócito → histamina → edema","Imunocomplexos → complemento → vasculite leucocitoclástica"],c:1,
e:"Lesão endotelial crônica → desvio para <b>Th2</b> → IL-4/IL-13 → <b>M2</b> → <b>TGF-β</b> → fibroblasto vira <b>miofibroblasto</b> → colágeno. Hipersensibilidade tipo IV com padrão Th2."},
{id:"p12",a:"pato",t:["p-sjogren-esclero"],s:"Paciente com esclerodermia apresenta, nos vasos de pequeno calibre, hiperplasia concêntrica da íntima. Essa lesão explica principalmente:",
o:["As úlceras digitais e a crise renal esclerodérmica","A síndrome sicca","O eritema malar","A formação de pannus","Os nódulos subcutâneos"],c:0,
e:"Vasculopatia obliterativa em <b>casca de cebola</b> → isquemia grave → <b>úlceras digitais</b> e <b>crise renal</b> (hipertensão maligna, ~20%)."},
{id:"p13",a:"pato",t:["p-sjogren-esclero"],s:"Sobre a esclerodermia, assinale a correta:",
o:["A principal causa de morte atual é a crise renal","O rim apresenta glomerulonefrite com alça de arame","Fibrose intersticial pulmonar e hipertensão pulmonar são hoje a principal causa de morte","O fenômeno de Raynaud é raro (cerca de 10%)","O acometimento esofágico atinge principalmente o terço superior"],c:2,
e:"Hoje: <b>pulmão</b> (fibrose intersticial + hipertensão pulmonar) é a principal causa de morte; a crise renal era a principal antes do tratamento atual. Raynaud ~90%. Esôfago: <b>2/3 inferiores</b>. Rim: sem alteração glomerular específica."},
{id:"p14",a:"pato",t:["p-edema"],s:"Paciente com síndrome nefrótica apresenta edema facial matinal que evolui para anasarca. O mecanismo principal do edema é:",
o:["Aumento da pressão hidrostática por obstrução venosa","Queda da pressão oncótica por perda urinária de albumina","Obstrução linfática","Aumento da permeabilidade por inflamação","Vasodilatação arteriolar"],c:1,
e:"Perda de albumina na urina → <b>↓ pressão oncótica</b> → edema generalizado (anasarca). Por ser sistêmica (albumina circula em todo o corpo), o edema é difuso. Líquido é transudato."},
{id:"p15",a:"pato",t:["p-edema"],s:"Uma punção de derrame pleural mostra líquido turvo, densidade 1,025, rico em proteínas e leucócitos. Qual condição é mais provável?",
o:["Insuficiência cardíaca congestiva","Síndrome nefrótica","Cirrose hepática","Pneumonia com pleurite","Desnutrição proteica (kwashiorkor)"],c:3,
e:"Densidade &gt; 1,020, turvo, rico em proteína e células = <b>exsudato</b> → inflamação com ↑ permeabilidade (pneumonia/pleurite). As outras causam transudato (&lt; 1,012)."},
{id:"p16",a:"pato",t:["p-edema"],s:"Mulher submetida a mastectomia com esvaziamento axilar desenvolve edema firme no braço, que não forma cacifo. O mecanismo e o tipo de líquido são:",
o:["Obstrução linfática — líquido rico em proteínas","Hipoalbuminemia — transudato","ICC direita — transudato","Inflamação — exsudato purulento","TVP — transudato"],c:0,
e:"<b>Linfedema</b>: drenagem linfática destruída → acumula os 10–15% que deveriam voltar, rico em proteínas; firme, <b>sem cacifo evidente</b>. Filariose → elefantíase pelo mesmo mecanismo."},
{id:"p17",a:"pato",t:["p-edema"],s:"Por que o paciente com insuficiência cardíaca tem edema agravado pelos rins?",
o:["O rim perde albumina na urina","O baixo débito é interpretado como hipovolemia, ativando o SRAA e a retenção de sódio e água","O rim produz menos eritropoetina","Há obstrução linfática renal","A aldosterona reduz a pressão hidrostática"],c:1,
e:"Sinal 'falso': ↓ perfusão renal → rim interpreta como hipovolemia → <b>SRAA</b> → aldosterona → retenção de Na⁺ e água → ↑ volume → ↑ pressão hidrostática → mais edema e mais sobrecarga (ciclo vicioso)."},
{id:"p18",a:"pato",t:["p-edema"],s:"Homem com cirrose e ascite volumosa apresenta febre, dor abdominal difusa e piora do estado geral, sem foco infeccioso evidente. Sobre o caso, é correto:",
o:["A ascite é um exsudato rico em imunoglobulinas","Trata-se de peritonite bacteriana espontânea; a ascite é transudato pobre em Ig e complemento, e bactérias intestinais translocam","A ascite é causada apenas por queda de albumina","O agente mais comum é S. aureus da pele","A congestão intestinal reforça a barreira epitelial"],c:1,
e:"Cirrose: hipertensão portal (↑ hidrostática) + ↓ albumina (↓ oncótica) → ascite = <b>transudato</b> pobre em Ig e complemento. Congestão afrouxa a barreira → <b>E. coli</b> transloca → <b>PBE</b>."},
{id:"p19",a:"pato",t:["p-edema"],s:"Necropsia de paciente com insuficiência ventricular esquerda crônica: pulmões endurecidos e acastanhados; à microscopia, macrófagos alveolares carregados de pigmento dourado. O achado e as células são:",
o:["Pneumonia lobar; células de Langhans","Induração marrom; células da insuficiência cardíaca (macrófagos com hemossiderina)","Antracose; macrófagos com carvão","Dano alveolar difuso; membranas hialinas","Infarto pulmonar; neutrófilos"],c:1,
e:"Congestão pulmonar crônica: hemácias extravasam, macrófagos fagocitam e acumulam <b>hemossiderina</b> = <b>células da insuficiência cardíaca</b>; septos fibrosados → <b>induração marrom</b>."},
{id:"p20",a:"pato",t:["p-edema"],s:"Fígado de paciente com insuficiência cardíaca direita crônica apresenta superfície de corte com áreas centrais vermelho-escuras e bordas amareladas. Qual a explicação?",
o:["Necrose hemorrágica periportal e esteatose centrolobular","Necrose hemorrágica centrolobular (mais distante do O₂) e esteatose periportal","Hepatite viral","Cirrose biliar","Infarto branco hepático"],c:1,
e:"<b>Fígado em noz-moscada</b>: congestão retrógrada nas veias hepáticas → zona <b>centrolobular</b> (mais pobre em O₂) sofre necrose hemorrágica; periportal apenas degeneração gordurosa."},
{id:"p21",a:"pato",t:["p-edema"],s:"Diferencie hiperemia de congestão: qual alternativa está correta?",
o:["Hiperemia é passiva e deixa o tecido cianótico","Congestão é ativa, com dilatação arteriolar","Hiperemia é ativa, com sangue oxigenado, tecido vermelho e quente; congestão é passiva, com sangue desoxigenado e cianose","Ambas cursam com exsudato","A congestão ocorre fisiologicamente no músculo em exercício"],c:2,
e:"Hiperemia: ativa, arteriolar, rubor e calor (exercício, inflamação), edema exsudato. Congestão: passiva, retorno venoso prejudicado, azulada e fria (TVP, ICC), edema transudato."},
{id:"p22",a:"pato",t:["p-hemorragia"],s:"Paciente com plaquetas de 8.000/mm³ apresenta pequenas manchas puntiformes de 1–2 mm nas pernas e sangramento gengival imediato após escovação. As lesões e o tipo de falha são:",
o:["Equimoses — falha da hemostasia secundária","Petéquias — falha da hemostasia primária","Hematomas — falha da fibrinólise","Púrpuras — escorbuto","Petéquias — falha do fator VIII"],c:1,
e:"<b>Petéquias</b> (1–2 mm) indicam trombocitopenia/defeito plaquetário = <b>hemostasia primária</b>; sangramento imediato e mucocutâneo."},
{id:"p23",a:"pato",t:["p-hemorragia"],s:"Menino com hemofilia A sofre extração dentária: o sangramento para inicialmente, mas recomeça horas depois. A explicação é:",
o:["Ausência de tampão plaquetário","Falha da vasoconstrição","O tampão plaquetário se forma, mas sem rede de fibrina estável ele se desfaz","Excesso de proteína C","Deficiência de fator de von Willebrand"],c:2,
e:"Falha da <b>hemostasia secundária</b> (fator VIII): o tampão primário segura no começo, mas sem fibrina (trombina insuficiente) se desfaz → sangramento tardio. Típico também: hemartrose."},
{id:"p24",a:"pato",t:["p-hemorragia"],s:"Na hemostasia primária, a adesão inicial da plaqueta ao subendotélio exposto ocorre principalmente pela ligação:",
o:["GpIIb/IIIa – fibrinogênio","GpIb – fator de von Willebrand","Fator tecidual – fator VII","Trombomodulina – trombina","ADP – receptor P2Y12"],c:1,
e:"Adesão: <b>GpIb ↔ FvW</b>. Depois a plaqueta ativa libera ADP e TXA2 e o <b>fibrinogênio liga GpIIb/IIIa</b> (agregação)."},
{id:"p25",a:"pato",t:["p-hemorragia"],s:"Qual elemento é o iniciador fisiológico (in vivo) da cascata de coagulação e qual enzima converte fibrinogênio em fibrina?",
o:["Fator XII; plasmina","Fator tecidual (III); trombina","Fator VIII; fator Xa","Colágeno; fator XIII","FvW; t-PA"],c:1,
e:"<b>Fator tecidual</b> + fator VII inicia; <b>trombina (IIa)</b> converte fibrinogênio em fibrina e ativa o fator XIII (ligações cruzadas)."},
{id:"p26",a:"pato",t:["p-hemorragia"],s:"Vítima de acidente com ferimento torácico evolui com hipotensão, turgência jugular e abafamento de bulhas. Qual hemorragia cavitária explica o quadro?",
o:["Hemotórax","Hemopericárdio com tamponamento cardíaco","Hemoperitônio","Hemartrose","Hematoma subdural"],c:1,
e:"<b>Hemopericárdio</b> → tamponamento: impede o enchimento diastólico; pode ser letal mesmo com pouco volume."},
{id:"p27",a:"pato",t:["p-hemorragia"],s:"Uma equimose de 10 dias tem coloração amarelo-acastanhada. Essa cor decorre de:",
o:["Hemoglobina oxigenada","Biliverdina","Hemossiderina","Melanina","Bilirrubina conjugada"],c:2,
e:"Hb desoxigenada (roxo) → heme-oxigenase → biliverdina (verde) → bilirrubina → <b>hemossiderina</b> (amarelo-acastanhado) até clarear."},
{id:"p28",a:"pato",t:["p-trombose"],s:"Na necrópsia, encontra-se massa no interior de uma artéria coronária, aderida à parede, com laminações alternadas claras e escuras. Trata-se de:",
o:["Coágulo post-mortem","Trombo formado em vida, com linhas de Zahn","Êmbolo gorduroso","Placa ateromatosa sem trombo","Vegetação de endocardite"],c:1,
e:"<b>Linhas de Zahn</b> (plaquetas+fibrina claras / hemácias escuras) e aderência = trombo em vida. Coágulo post-mortem é gelatinoso, não aderido ('gordura de galinha' e 'geleia de groselha')."},
{id:"p29",a:"pato",t:["p-trombose"],s:"Mulher, 28 anos, em uso de anticoncepcional oral, após voo de 12 horas apresenta dor e edema unilateral da panturrilha. Quais componentes da tríade de Virchow estão presentes?",
o:["Apenas lesão endotelial","Estase e hipercoagulabilidade","Turbulência e lesão endotelial","Apenas hipercoagulabilidade","Turbulência e hipercoagulabilidade"],c:1,
e:"Imobilização no voo = <b>estase</b> (principal fator da trombose venosa); anticoncepcional = <b>hipercoagulabilidade</b> adquirida."},
{id:"p30",a:"pato",t:["p-trombose"],s:"Jovem de 22 anos com segundo episódio de TVP sem fator desencadeante e mãe com história de trombose. O teste mostra resistência à proteína C ativada. O diagnóstico mais provável é:",
o:["Deficiência de antitrombina III","Fator V de Leiden","Síndrome antifosfolipídio","Hiper-homocisteinemia","Mutação da protrombina G20210A"],c:1,
e:"<b>Fator V de Leiden</b>: fator V resistente à inativação pela proteína C → perde via antitrombótica (risco 5–50×)."},
{id:"p31",a:"pato",t:["p-trombose"],s:"Paciente internado em uso de heparina não fracionada há 7 dias apresenta queda de 60% nas plaquetas e, simultaneamente, isquemia aguda de membro inferior. Qual a explicação?",
o:["Sangramento por plaquetopenia","Trombocitopenia induzida por heparina: IgG anti-PF4/heparina ativa plaquetas, causando consumo e trombose","Deficiência de vitamina K","CID por sepse","Deficiência de proteína S"],c:1,
e:"<b>TIH</b>: 5–10 dias após HNF; heparina + PF4 → <b>IgG</b> → ativa plaquetas → consumo (plaquetopenia) + liberação de pró-coagulantes. <b>A principal complicação é trombose</b> (gangrena, AVE, IAM, necrose de pele)."},
{id:"p32",a:"pato",t:["p-trombose"],s:"Sobre trombose arterial versus venosa, assinale a correta:",
o:["O trombo venoso é rico em plaquetas e fibrina","A estase é o principal fator da trombose arterial","O trombo arterial associa-se a fluxo rápido, turbulência e lesão endotelial, e é rico em plaquetas e fibrina","A complicação típica da trombose venosa profunda é o infarto agudo do miocárdio","A turbulência mantém as plaquetas no centro do vaso"],c:2,
e:"Arterial: fluxo rápido, turbulência, lesão endotelial (aterosclerose), <b>plaquetas + fibrina</b>, complicação IAM/AVC. Venoso: estase, <b>fibrina + hemácias</b>, complicação embolia pulmonar."},
{id:"p33",a:"pato",t:["p-trombose"],s:"Citocinas inflamatórias ativam o endotélio e criam estado pró-trombótico. Quais alterações ocorrem?",
o:["↑ trombomodulina, ↑ proteína C, ↑ t-PA","↓ trombomodulina, ↓ proteína C, ↓ TFPI, ↑ PAI e ↓ t-PA","↑ NO e ↑ prostaciclina","↓ fator tecidual e ↓ FvW","↑ plasmina e ↑ D-dímero apenas"],c:1,
e:"Efeito pró-coagulante: ↓ trombomodulina, ↓ proteína C, ↓ inibidor da via do fator tecidual (↑ trombina). Antifibrinolítico: <b>↑ PAI e ↓ t-PA</b>."},
{id:"p34",a:"pato",t:["p-trombose"],s:"Um trombo antigo em artéria femoral foi invadido por fibroblastos e capilares, formando novos canais, mas o fluxo não voltou ao normal. Esse destino é chamado:",
o:["Resolução","Propagação","Embolização","Organização com recanalização","Calcificação distrófica primária"],c:3,
e:"<b>Organização</b>: invasão por células e tecido conjuntivo, formação de novos canais (recanalização), sem garantir fluxo normal. Resolução seria lise por fibrinólise (trombo recente)."},
{id:"p35",a:"pato",t:["p-embolia"],s:"Homem de 60 anos no 5º dia pós-operatório de prótese de quadril apresenta dispneia súbita, taquicardia e dor torácica. Qual o trajeto do êmbolo mais provável?",
o:["Átrio esquerdo → aorta → artéria pulmonar","Veia profunda da perna → veia ilíaca → cava inferior → átrio direito → ventrículo direito → artéria pulmonar","Artéria femoral → aorta → pulmão","Veia porta → fígado → pulmão","Veia jugular → cava superior → átrio esquerdo"],c:1,
e:"TVP → <b>cava inferior → AD → VD → artéria pulmonar</b>. O pulmão é o primeiro leito capilar após o coração direito. Sobrecarrega o VD e reduz oxigenação."},
{id:"p36",a:"pato",t:["p-embolia"],s:"Jovem, 48 horas após fratura de fêmur, desenvolve insuficiência respiratória, confusão mental e petéquias no tórax e axilas. Diagnóstico provável:",
o:["Tromboembolia pulmonar","Embolia gordurosa","Embolia gasosa","Embolia por líquido amniótico","Choque neurogênico"],c:1,
e:"<b>Embolia gordurosa</b>: fratura de osso longo; sintomas em <b>24–72 h</b>; tríade: insuficiência respiratória + alterações neurológicas + <b>petéquias</b>."},
{id:"p37",a:"pato",t:["p-embolia"],s:"Durante a passagem de cateter venoso central, ocorre entrada de ar e o paciente fica dispneico e hipotenso. Qual conduta descrita em aula?",
o:["Decúbito lateral direito e anticoagulação","Oxigênio a 100%, decúbito lateral esquerdo e câmara hiperbárica","Trombólise imediata","Elevar a cabeceira a 90° e diurético","Heparina não fracionada"],c:1,
e:"Embolia gasosa: <b>O₂ 100%, decúbito lateral esquerdo</b> (evita que a bolha atinja a circulação pulmonar) e <b>câmara hiperbárica</b>."},
{id:"p38",a:"pato",t:["p-embolia"],s:"Puérpera, minutos após parto, apresenta dispneia súbita, hipotensão, cianose e sangramento difuso pelos locais de punção. Na necrópsia, células escamosas fetais e lanugo nas arteríolas pulmonares. Qual complicação explica o sangramento?",
o:["Trombocitopenia induzida por heparina","CID por embolia de líquido amniótico","Hemofilia adquirida","Deficiência de vitamina K","Choque neurogênico"],c:1,
e:"Embolia por <b>líquido amniótico</b>: células escamosas, lanugo, mucina na circulação materna; a <b>CID é característica</b> → consumo de plaquetas e fatores → hemorragia."},
{id:"p39",a:"pato",t:["p-embolia"],s:"Por que, na CID, o paciente trombosa e sangra ao mesmo tempo?",
o:["Porque há deficiência hereditária de fator VIII","Porque microtrombos consomem plaquetas e fatores de coagulação e a fibrinólise é ativada","Porque a heparina endógena é inativada","Porque há excesso de proteína C","Porque o FvW está ausente"],c:1,
e:"<b>Coagulopatia de consumo</b>: a trombose microvascular disseminada consome plaquetas e fatores + ativa fibrinólise → evolui para hemorragia (AVE hemorrágico, choque)."},
{id:"p40",a:"pato",t:["p-infarto"],s:"Qual dos órgãos abaixo tipicamente sofre infarto vermelho (hemorrágico)?",
o:["Coração","Baço","Rim","Pulmão","Todos os anteriores"],c:3,
e:"Infarto vermelho: tecido frouxo e <b>circulação dupla</b> (pulmão, intestino), oclusão venosa (testículo, ovário), congestão prévia, reperfusão. Coração, baço e rim = infarto <b>branco</b>."},
{id:"p41",a:"pato",t:["p-infarto"],s:"Adolescente com dor escrotal súbita e intensa há 8 horas. Na cirurgia, o testículo está escuro e edemaciado. Qual o mecanismo do infarto?",
o:["Oclusão arterial em órgão de circulação dupla","Torção com colapso da veia eferente única: sangue entra mas não sai, pressão sobe e o fluxo arterial para — infarto hemorrágico","Embolia gordurosa","Vasculite por imunocomplexos","Infarto branco por artéria terminal"],c:1,
e:"Regra: oclusão venosa costuma dar só congestão. Exceção: órgão com <b>veia eferente única</b> (testículo, ovário) — na torção, a veia colapsa primeiro → <b>infarto vermelho</b>."},
{id:"p42",a:"pato",t:["p-infarto"],s:"Paciente falece 3 dias após AVC isquêmico extenso. Que tipo de necrose se espera no tecido cerebral e como ele cicatriza?",
o:["Necrose coagulativa; cicatriz colágena","Necrose liquefativa; cavitação e cicatriz glial (astrócitos)","Necrose caseosa; granuloma","Necrose fibrinoide; espessamento vascular","Necrose gordurosa; saponificação"],c:1,
e:"SNC: pouco estroma, muita enzima (micróglia/neutrófilos), muito lipídio (mielina) → <b>necrose liquefativa</b>, cavitação, <b>sem fibrose</b>, cicatriz glial (gliose)."},
{id:"p43",a:"pato",t:["p-infarto"],s:"Paciente morre 2 horas após oclusão coronariana. Qual achado é esperado no miocárdio?",
o:["Necrose coagulativa franca com neutrófilos","Tecido de granulação","Cicatriz fibrosa","Nenhuma alteração macroscópica ou histológica evidente","Necrose liquefativa"],c:3,
e:"Minutos a poucas horas: <b>nada visível</b>. Necrose coagulativa: 4–12 h; macroscopia: após 18–24 h; inflamação aguda nas margens: 1–2 dias."},
{id:"p44",a:"pato",t:["p-infarto"],s:"Paciente com endocardite infecciosa da valva mitral apresenta dor súbita no hipocôndrio esquerdo e febre persistente. A tomografia mostra lesão em cunha no baço. O diagnóstico e a evolução possível são:",
o:["Infarto vermelho asséptico; resolução completa","Infarto séptico esplênico; evolução para abscesso","Hematoma subcapsular traumático","Linfoma esplênico","Congestão passiva crônica"],c:1,
e:"Êmbolo de <b>vegetação infectada</b> → <b>infarto séptico</b>; tecido necrótico sem perfusão é ótimo meio de cultura, livre do sistema imune → abscesso."},
{id:"p45",a:"pato",t:["p-infarto"],s:"Ordene os neurônios, miócitos e fibroblastos pelo tempo de isquemia tolerado até lesão irreversível:",
o:["Fibroblasto 3–4 min < miócito 20–30 min < neurônio horas","Neurônio 3–4 min < miócito 20–30 min < fibroblasto horas","Miócito 3–4 min < neurônio 20–30 min < fibroblasto horas","Todos toleram cerca de 20 minutos","Neurônio horas < miócito 20–30 min < fibroblasto 3–4 min"],c:1,
e:"Vulnerabilidade: <b>neurônio 3–4 min, miócito 20–30 min, fibroblasto horas</b>."},
{id:"p46",a:"pato",t:["p-infarto"],s:"Após angioplastia tardia de coronária ocluída há 6 horas, a área infartada mostra hemorragia intersticial. A explicação é:",
o:["Infarto séptico","Reperfusão: o sangue chega a vasos já lesados e as hemácias extravasam","Congestão prévia por insuficiência cardíaca direita","Circulação dupla do miocárdio","Embolia gordurosa"],c:1,
e:"<b>Reperfusão</b> é um dos 5 caminhos do infarto vermelho: o fluxo restabelecido encontra microvasos lesados → hemácias extravasam."},
{id:"p47",a:"pato",t:["p-choque"],s:"Homem, 58 anos, com IAM extenso de parede anterior, evolui com PA 75/50, pele fria e pegajosa, turgência jugular, terceira bulha e estertores pulmonares. Qual o tipo de choque?",
o:["Hipovolêmico","Cardiogênico","Séptico","Neurogênico","Anafilático"],c:1,
e:"Falência da bomba (IAM é a causa mais comum). <b>Turgência jugular, B3 e congestão pulmonar</b> distinguem do hipovolêmico."},
{id:"p48",a:"pato",t:["p-choque"],s:"Motociclista com trauma raquimedular cervical apresenta PA 70/40, FC 48 bpm, pele quente e paralisia flácida dos quatro membros. O choque é:",
o:["Hipovolêmico por hemorragia oculta","Neurogênico","Cardiogênico","Séptico","Obstrutivo por tamponamento"],c:1,
e:"<b>Neurogênico</b>: perda do tônus simpático → vasodilatação → <b>hipotensão com bradicardia</b>, hipotermia, paralisia flácida abaixo da lesão. Hipovolêmico teria taquicardia."},
{id:"p49",a:"pato",t:["p-choque"],s:"Qual dos seguintes NÃO é sinal precoce de má perfusão no choque?",
o:["Extremidades frias","Enchimento capilar lento","Oligúria","Lactato crescente","Hipotensão é obrigatória para o diagnóstico"],c:4,
e:"<b>Hipotensão não é sinônimo de choque</b>: pode haver choque antes da queda da PA. Sinais precoces: extremidades frias, enchimento lento, alteração de consciência, oligúria, lactato ↑."},
{id:"p50",a:"pato",t:["p-choque"],s:"No estágio progressivo do choque, o que perpetua o ciclo vicioso?",
o:["Vasoconstrição periférica mantida por catecolaminas","Acidose láctica que paralisa esfíncteres pré-capilares, gerando estase, anóxia endotelial e microtrombos","Ruptura de lisossomos com recuperação após volume","Aumento do débito cardíaco","Retenção de sódio pelo SRAA, que corrige a perfusão"],c:1,
e:"Progressivo: anaerobiose → <b>acidose láctica</b> → paralisia dos esfíncteres pré-capilares → estase, anóxia endotelial, microtrombos, oligúria. Ruptura de lisossomos é do irreversível."},
{id:"p51",a:"pato",t:["p-choque"],s:"Paciente falece após choque prolongado. A microscopia renal mostra desnudamento do epitélio tubular cortical, perda da borda em escova e cilindros proteicos. O diagnóstico é:",
o:["Glomerulonefrite proliferativa","Necrose tubular aguda isquêmica","Pielonefrite aguda","Nefrite lúpica","Infarto renal branco"],c:1,
e:"<b>NTA isquêmica</b> → insuficiência renal aguda e anúria. No pulmão do mesmo paciente: dano alveolar difuso com membranas hialinas."},
{id:"p52",a:"pato",t:["p-choque"],s:"No pulmão de paciente em choque séptico encontra-se espessamento dos septos e membranas eosinofílicas revestindo os alvéolos. Trata-se de:",
o:["Induração marrom","Dano alveolar difuso com membranas hialinas","Infarto pulmonar hemorrágico","Pneumonia lobar","Enfisema"],c:1,
e:"<b>Dano alveolar difuso</b>: septos espessados e permeáveis + exsudato rico em fibrina → <b>membranas hialinas</b> rosadas → bloqueio da troca gasosa."},
{id:"p53",a:"pato",t:["p-choque"],s:"Qual característica diferencia clinicamente o choque séptico inicial dos choques hipovolêmico e cardiogênico?",
o:["Pele fria e pálida","Bradicardia","Pele quente e ruborizada pela vasodilatação","Turgência jugular","Ausência de taquicardia"],c:2,
e:"Choque séptico inicial ('quente'): vasodilatação disseminada → <b>pele quente e ruborizada</b>. Hipovolêmico e cardiogênico: pele fria."},
{id:"p54",a:"pato",t:["p-hemorragia","p-choque"],s:"Gravidade de uma hemorragia: qual perda volêmica aguda costuma levar ao choque hipovolêmico, segundo a aula?",
o:["Mais de 5%","Mais de 10%","Mais de 20%","Mais de 50%","Qualquer volume em adultos"],c:2,
e:"Perder <b>&gt; 20%</b> do volume sanguíneo → choque hipovolêmico. Os outros fatores de gravidade: localização (crânio) e destino do ferro."},
/* ======================= IMUNOLOGIA ======================= */
{id:"i1",a:"imuno",t:["i-transplante"],s:"Paciente recebe rim de doador falecido. Minutos após a anastomose vascular, o enxerto fica cianótico, mosqueado e flácido. Qual o mecanismo?",
o:["Via indireta com CD4 Th1","Anticorpos pré-formados contra HLA/ABO do doador, ativando complemento e coagulação","CD8 citotóxicos via direta","Linfócitos T do doador atacando o receptor","Toxicidade da ciclosporina"],c:1,
e:"<b>Rejeição hiperaguda</b> (minutos-horas): anticorpos <b>pré-formados</b> (gestações, transfusões, transplantes prévios) → complemento, NK, M1 e coagulação → trombose maciça e necrose hemorrágica. Irreversível; prevenida por ABO e crossmatch."},
{id:"i2",a:"imuno",t:["i-transplante"],s:"Na via DIRETA de alorreconhecimento:",
o:["APCs do receptor processam peptídeos do doador e apresentam no MHC próprio","APCs do doador migram para linfonodos do receptor e apresentam MHC intacto do doador aos linfócitos T do receptor","APCs do receptor adquirem MHC do doador por exossomos","Linfócitos B reconhecem ABO","T do doador reconhecem tecidos do receptor"],c:1,
e:"Direta = 'o espião': APC <b>do doador</b> mostra MHC intacto, sem processamento → rápida, agressiva, principal motor da <b>rejeição aguda</b>. A alternativa A é a indireta (crônica); C é a semidireta; E é DECH."},
{id:"i3",a:"imuno",t:["i-transplante"],s:"Transplantado renal há 6 anos com perda lenta e progressiva da função. Biópsia: espessamento concêntrico da íntima arterial, fibrose intersticial e atrofia tubular. Qual a via predominante?",
o:["Via direta com CD8","Via indireta com CD4 Th1 liberando IFN-γ","Anticorpos pré-formados","Deficiência de complemento","Via semidireta exclusivamente"],c:1,
e:"<b>Rejeição crônica</b>: via <b>indireta</b>, CD4 Th1 (IFN-γ), inflamação silenciosa → <b>arteriosclerose do enxerto</b>, fibrose, atrofia. Irreversível, principal causa de perda tardia; associa-se a má adesão ao imunossupressor."},
{id:"i4",a:"imuno",t:["i-transplante"],s:"Rejeição aguda celular, ocorrida na 3ª semana pós-transplante, caracteriza-se histologicamente por:",
o:["Trombose maciça e necrose hemorrágica","Endotelialite e inflamação intersticial; frequentemente reversível","Arteriosclerose do enxerto","Fibrose sem inflamação","Granulomas caseosos"],c:1,
e:"Aguda (dias a semanas): celular (CD8/CD4) e humoral (anti-HLA <i>de novo</i>) → <b>endotelialite</b> e infiltrado intersticial; frequentemente reversível com imunossupressão rápida e intensa."},
{id:"i5",a:"imuno",t:["i-transplante"],s:"No crossmatch, o soro do receptor é incubado com linfócitos do doador, seguido de anti-Ig humana e complemento. Houve lise celular. A interpretação é:",
o:["Compatível — pode transplantar","Reatividade: há anticorpos pré-formados anti-doador; não transplantar","O receptor tem deficiência de complemento","O doador tem HLA idêntico","Indica apenas incompatibilidade Rh"],c:1,
e:"Lise = <b>reatividade</b> → há anticorpos anti-HLA do doador → risco de hiperaguda → <b>não transplantar</b>. O funil: ABO → tipagem HLA (A, B, DR) → crossmatch."},
{id:"i6",a:"imuno",t:["i-transplante"],s:"Tacrolimus e ciclosporina atuam em qual sinal da ativação do linfócito T?",
o:["Sinal 2, bloqueando B7–CD28","Sinal 1, inibindo calcineurina e impedindo NFAT de transcrever IL-2","Sinal 3, inibindo mTOR","Depleção de linfócitos B","Bloqueio do CSF-1R"],c:1,
e:"Sinal 1 (TCR–MHC) → Ca²⁺ → <b>calcineurina</b> → NFAT → IL-2. Belatacepte = sinal 2 (CTLA4-Ig); sirolimo/everolimo = sinal 3 (mTOR); axatilimabe = CSF-1R."},
{id:"i7",a:"imuno",t:["i-transplante"],s:"Belatacepte (CTLA4-Ig) deixa o linfócito T anérgico porque:",
o:["Inibe a calcineurina","Liga-se a B7 na APC, impedindo a coestimulação via CD28","Bloqueia o receptor de IL-2","Inibe a síntese de purinas","Depleta timócitos"],c:1,
e:"Bloqueia o <b>sinal 2</b> (coestimulação, 'dupla chave'): sem B7–CD28, o T que reconhece o antígeno fica <b>anérgico</b> — mesmo princípio da tolerância periférica."},
{id:"i8",a:"imuno",t:["i-transplante"],s:"Criança submetida a transplante de medula óssea apresenta, no 30º dia, exantema maculopapular, icterícia e diarreia volumosa. O diagnóstico e o mecanismo são:",
o:["Rejeição aguda: T do receptor atacam a medula","DECH: linfócitos T do doador reconhecem aloantígenos do hospedeiro e lesam pele, fígado e TGI","Rejeição hiperaguda","Infecção por CMV exclusivamente","Deficiência de IgA"],c:1,
e:"<b>Doença do enxerto contra o hospedeiro</b>: o enxerto traz T imunocompetentes → atacam <b>pele, fígado e trato gastrointestinal</b>. Na rejeição é o oposto."},
{id:"i9",a:"imuno",t:["i-transplante"],s:"O axatilimabe, aprovado para DECH crônica, tem como alvo:",
o:["Calcineurina do linfócito T","CD25","CSF-1R (CD115) de monócitos e macrófagos, reduzindo macrófagos patogênicos e pró-fibróticos","CD20 do linfócito B","mTORC1"],c:2,
e:"Axatilimabe bloqueia <b>CSF-1R (CD115)</b> (ligantes CSF-1/M-CSF e IL-34) → ↓ monócitos pró-inflamatórios e macrófagos pró-fibróticos → ↓ inflamação e fibrose. <b>Não</b> age primariamente no T."},
{id:"i10",a:"imuno",t:["i-transplante"],s:"Sobre o HLA, assinale a correta:",
o:["Classe I (DP, DQ, DR) está em todas as células nucleadas","Classe II (A, B, C) apresenta ao CD8","Está no cromossomo 6; classe I (A, B, C) em células nucleadas → CD8; classe II (DP, DQ, DR) em APCs → CD4","Isoenxertos entre gêmeos univitelinos têm alto risco de rejeição","O HLA é pouco polimórfico"],c:2,
e:"HLA no <b>cromossomo 6</b>, o sistema mais polimórfico (DRB1 &gt; 3.400 alelos). Classe I = A, B, C → CD8. Classe II = DP, DQ, DR → CD4."},
{id:"i11",a:"imuno",t:["i-idinata"],s:"Menino de 4 anos com abscessos recorrentes de pele, fígado e linfonodos por S. aureus e uma pneumonia por Aspergillus. Biópsia com granulomas. Hemograma com neutrófilos normais. Qual exame confirma a hipótese?",
o:["Dosagem de imunoglobulinas","Teste DHR-123 (ou NBT) avaliando a explosão respiratória","Contagem de CD18 por citometria","CH50","Pesquisa de TRECs"],c:1,
e:"<b>DGC</b>: defeito da <b>NADPH oxidase</b> → sem EROs → catalase-positivos e fungos sobrevivem dentro do fagócito → granulomas. Falha de <b>função</b>, não de número: DHR-123/NBT reduzidos."},
{id:"i12",a:"imuno",t:["i-idinata"],s:"Recém-nascido com queda tardia do coto umbilical, onfalite sem pus, leucocitose persistente de 45.000/mm³ e cicatrização ruim. Qual defeito?",
o:["NADPH oxidase","Integrina β2 (CD18) — LAD I","Deficiência de C3","Deficiência de BTK","Cadeia γ comum"],c:1,
e:"<b>LAD I</b>: sem CD18 não há adesão firme → leucócito não transmigra: leucocitose no sangue, <b>ausência de pus</b>, cicatrização deficiente (queda tardia do coto é clássica)."},
{id:"i13",a:"imuno",t:["i-idinata"],s:"Qual LAD cursa também com sangramentos recorrentes e por quê?",
o:["LAD I, porque falta CD18 nas plaquetas","LAD II, por falta de fucose","LAD III, por defeito na sinalização que ativa integrinas de leucócitos e de plaquetas","Nenhuma cursa com sangramento","LAD II, porque não há selectinas"],c:2,
e:"<b>LAD III</b>: defeito de ativação de integrinas (inclusive GpIIb/IIIa plaquetária) → além das infecções, <b>sangramentos</b>. Ponte com hemostasia primária!"},
{id:"i14",a:"imuno",t:["i-idinata"],s:"Adolescente com terceiro episódio de meningite meningocócica. O defeito mais provável está em:",
o:["C1q","C3","Componentes terminais C5–C9 (MAC)","Inibidor de C1","NADPH oxidase"],c:2,
e:"Deficiência de <b>C5–C9</b>: sem MAC a <i>Neisseria</i> não é lisada → meningites recorrentes e sepse fulminante. Triagem: CH50."},
{id:"i15",a:"imuno",t:["i-idinata"],s:"Mulher de 25 anos com episódios recorrentes de edema de face e lábios sem urticária e sem prurido, um episódio de edema de laringe, e mãe com quadro semelhante. Qual o mecanismo?",
o:["Hipersensibilidade tipo I mediada por IgE","Deficiência do inibidor de C1 com ativação contínua da via clássica e excesso de C4a, C3a e C5a","Deficiência de C3","Deficiência de IgA","Mastocitose"],c:1,
e:"<b>Angioedema hereditário</b>: falta C1-INH → via clássica sempre ligada → anafilatoxinas ↑ permeabilidade. Excesso de ativação, não infecção. Diferente da anafilaxia (IgE, urticária)."},
{id:"i16",a:"imuno",t:["i-idinata"],s:"A deficiência de qual componente do complemento cursa com infecções graves por piogênicos, glomerulonefrite e doença autoimune, por comprometer a principal opsonina?",
o:["C1-INH","C3","C9","Properdina","MBL"],c:1,
e:"<b>C3</b> está no centro das 3 vias; C3b é a principal opsonina. Falta → piogênicos (S. aureus, sepse), Gram-negativos, glomerulonefrite por imunocomplexos."},
{id:"i17",a:"imuno",t:["i-idadapt"],s:"Menino de 14 meses com otites, sinusites e pneumonias de repetição desde os 7 meses e diarreia por Giardia. Ao exame, amígdalas quase ausentes. Laboratório: CD19 indetectável, IgG, IgA e IgM muito baixas. Diagnóstico:",
o:["Imunodeficiência comum variável","Agamaglobulinemia ligada ao X (Bruton)","Hiper-IgM","Deficiência seletiva de IgA","DiGeorge"],c:1,
e:"<b>Bruton (XLA)</b>: mutação em <b>BTK</b> (X) → B não matura → <b>ausência de B</b> (CD19/CD20), todas as Ig baixas, amígdalas/linfonodos pequenos. Aparece após 6 meses (fim da IgG materna)."},
{id:"i18",a:"imuno",t:["i-idadapt"],s:"Mulher de 28 anos com sinusites e pneumonias de repetição, diarreia crônica e púrpura trombocitopênica autoimune. Linfócitos B presentes; IgG e IgA baixas; resposta vacinal pobre. O diagnóstico e o risco a vigiar:",
o:["Bruton; linfoma de Burkitt","CVID; linfoma e câncer gástrico","Deficiência de IgA; anafilaxia","SCID; BCG-ose","Hiper-IgM; Pneumocystis"],c:1,
e:"<b>CVID</b>: B presente mas não vira plasmócito; IgG e IgA ↓; adultos; autoimunidade, linfoproliferação, <b>linfoma e câncer gástrico</b>."},
{id:"i19",a:"imuno",t:["i-idadapt"],s:"Menino com pneumonia por Pneumocystis jirovecii e diarreia por Cryptosporidium. IgM elevada; IgG, IgA e IgE muito baixas. O defeito está em:",
o:["BTK","Interação CD40L (T CD4) – CD40 (B), impedindo a troca de classe","NADPH oxidase","Cadeia γ comum","Receptor de IL-12"],c:1,
e:"<b>Síndrome de hiper-IgM</b>: falha da troca de classe (CD40L/CD40/AID). O B só produz IgM. Pneumocystis e Cryptosporidium refletem também a falha do diálogo T-macrófago via CD40L."},
{id:"i20",a:"imuno",t:["i-idadapt"],s:"Recém-nascido com fenda palatina, sopro cardíaco (tetralogia de Fallot), orelhas de implantação baixa e convulsão por hipocalcemia no 3º dia. O defeito imunológico esperado é:",
o:["Ausência de linfócitos B","Redução de linfócitos T por hipoplasia tímica (deleção 22q11.2)","Deficiência de C1-INH","Neutropenia congênita","Excesso de IgE"],c:1,
e:"<b>DiGeorge</b>: falha das bolsas faríngeas → hipoplasia de <b>timo</b> (T ↓) e <b>paratireoides</b> (hipocalcemia) + cardiopatia + dismorfias. RX sem sombra tímica; FISH 22q11.2."},
{id:"i21",a:"imuno",t:["i-idadapt"],s:"Lactente de 4 meses com candidíase oral persistente, diarreia crônica, déficit de crescimento e disseminação do BCG. Linfopenia intensa; teste do pezinho com TRECs ausentes. Linfócitos T e NK ausentes, B presentes. Qual a causa mais provável?",
o:["Deficiência de ADA","SCID ligada ao X por defeito na cadeia γ comum","Defeito de RAG (V(D)J)","DiGeorge parcial","Bruton"],c:1,
e:"<b>T⁻ B⁺ NK⁻</b> = SCID ligada ao X (γc): sem IL-7R → sem T; sem IL-15R → sem NK; B presente mas sem ajuda. ADA: T⁻B⁻NK⁻; RAG: T⁻B⁻NK⁺."},
{id:"i22",a:"imuno",t:["i-idadapt"],s:"Criança com infecção disseminada após BCG e infecções recorrentes por micobactérias atípicas. Th1 não se forma mesmo com IL-12 abundante. O defeito e o tratamento adjuvante são:",
o:["Deficiência de BTK; IGIV","Deficiência do receptor de IL-12; IFN-γ","Deficiência de C5; vacina meningocócica","Defeito de CD18; transplante","Deficiência de IgA; nenhum"],c:1,
e:"Sem <b>IL-12R</b> no CD4 → sem Th1 → macrófagos mal ativados → <b>micobactérias</b>, reação ao BCG. IFN-γ recruta/ativa M1, NK, CD8 (o Th1 continua deficiente)."},
{id:"i23",a:"imuno",t:["i-idadapt"],s:"Homem de 30 anos, assintomático, descobre IgA sérica &lt; 7 mg/dL com IgG e IgM normais em exame de rotina. Assinale a correta:",
o:["É a imunodeficiência primária seletiva mais comum; a maioria é assintomática, mas pode ter infecções de mucosa, alergias e autoimunidade","Deve receber IGIV obrigatoriamente","A resposta vacinal está abolida","Os linfócitos B estão ausentes","É causada por mutação em BTK"],c:0,
e:"<b>Deficiência seletiva de IgA</b>: falha na troca para cadeia α; mais comum; resposta vacinal normal; mucosas, giardíase, alergias, autoimunidade (celíaca). Cuidado: sorologia celíaca IgA falso-negativa."},
{id:"i24",a:"imuno",t:["i-idadapt"],s:"Até qual dia de vida deve ser colhido o teste do pezinho para pesquisa de TRECs, e por quê?",
o:["Até o 30º dia, para dar tempo aos T maturarem","Até o 5º dia, para não sofrer influência do sistema imune materno","Após 6 meses, quando a IgG materna acaba","No 1º dia apenas","Não se usa teste do pezinho para SCID"],c:1,
e:"TRECs = marcadores de maturação tímica do T. Colher até o <b>5º dia</b> para não sofrer influência materna. Ausentes na SCID."},
{id:"i25",a:"imuno",t:["i-idinata"],s:"Dos 10 sinais de alerta para imunodeficiência primária, qual NÃO faz parte da lista?",
o:["Duas ou mais pneumonias no último ano","Quatro ou mais otites novas no último ano","Efeito adverso ao BCG","Febre isolada única por virose comum","História familiar de imunodeficiência"],c:3,
e:"Sinais: ≥2 pneumonias/ano; ≥4 otites/ano; estomatites/monilíase &gt;2 meses; abscessos de repetição; 1 infecção sistêmica grave; diarreia crônica; asma grave/autoimune; BCG/micobactéria; fenótipo sindrômico; história familiar."},
{id:"i26",a:"imuno",t:["i-dai"],s:"Na artrite reumatoide, a erosão óssea periarticular decorre principalmente de:",
o:["Ação direta do fator reumatoide sobre o osso","RANKL expresso por T ativados e estroma sinovial, que ativa RANK em pré-osteoclastos","Deficiência de vitamina D","Depósito de cristais","Isquemia por vasculite"],c:1,
e:"<b>RANKL → RANK</b> → maturação, sobrevivência e atividade do osteoclasto → erosão. TNF-α, IL-1 e IL-6 também ativam osteoclastos."},
{id:"i27",a:"imuno",t:["i-dai"],s:"Na doença celíaca, qual etapa aumenta a afinidade da gliadina pelo HLA-DQ2/DQ8?",
o:["Citrulinação por PAD","Desaminação pela transglutaminase tecidual (tTG)","Glicosilação pela fucosiltransferase","Fosforilação pela BTK","Clivagem pela calcineurina"],c:1,
e:"<b>tTG desamina a gliadina</b> → maior afinidade por HLA-DQ2/DQ8 → CD4 (IFN-γ, TNF-α). Marcador principal: <b>anti-tTG</b>."},
{id:"i28",a:"imuno",t:["i-dai"],s:"Na doença celíaca, a lesão epitelial direta e a atrofia vilositária são causadas também por um componente inato representado por:",
o:["Neutrófilos da lâmina própria","Linfócitos intraepiteliais CD8+ ativados diretamente pela gliadina","Eosinófilos ativados por IgE","Mastócitos","Plasmócitos IgA"],c:1,
e:"A gliadina ativa diretamente epitélio e <b>linfócitos intraepiteliais CD8+</b> → dano epitelial, atrofia de vilosidades, má absorção."},
{id:"i29",a:"imuno",t:["i-dai"],s:"Mulher de 32 anos com ptose palpebral e diplopia que pioram ao fim do dia e melhoram com repouso. TC de tórax com massa mediastinal anterior. Qual o mecanismo?",
o:["Tipo IV com CD8 contra neurônios motores","Autoanticorpos IgG anti-receptor de acetilcolina que bloqueiam, internalizam o receptor e ativam complemento","Imunocomplexos depositados no nervo","Desmielinização central por Th17","Anticorpos estimuladores do receptor"],c:1,
e:"<b>Miastenia gravis</b> (tipo II): anti-AChR (~85%) IgG1/IgG3 → bloqueio, endocitose (↓ receptores) e lesão pós-sináptica por complemento. Massa mediastinal = <b>timoma</b> (gatilho)."},
{id:"i30",a:"imuno",t:["i-dai"],s:"Sobre o DM1, assinale a correta:",
o:["Os autoanticorpos anti-GAD65 destroem as células β","Os linfócitos T CD8+ destroem diretamente as células β; os autoanticorpos são marcadores","Os sintomas surgem com 20% das células β destruídas","Associa-se principalmente a HLA-B27","É hipersensibilidade tipo III"],c:1,
e:"No DM1, quem mata é o <b>CD8</b> (tipo IV). Anti-insulina, anti-GAD65, anti-IA-2, anti-ZnT8 são <b>marcadores</b>. Sintomas com <b>80–90%</b> destruído. HLA-DR3, DR4, DQ8."},
{id:"i31",a:"imuno",t:["i-dai"],s:"Na esclerose múltipla, como os linfócitos T autorreativos chegam ao SNC?",
o:["São gerados dentro do SNC pela micróglia","Ativados na periferia (ex.: linfonodos cervicais), expressam moléculas de adesão e atravessam a barreira hematoencefálica","Por mimetismo com a mielina sem sair do sangue","Por transporte em hemácias","Não chegam: a lesão é só por anticorpos"],c:1,
e:"CD4 reconhecem MBP/MOG/PLP, são ativados fora do SNC, expressam <b>moléculas de adesão</b> e cruzam a BHE; liberam IFN-γ, IL-17, TNF-α; micróglia/macrófagos fagocitam mielina."},
{id:"i32",a:"imuno",t:["i-dai"],s:"Jovem com diarreia crônica, dor em fossa ilíaca direita e fístula perianal. Colonoscopia: úlceras profundas em íleo terminal com áreas preservadas; biópsia com inflamação transmural e granulomas não caseosos. Qual gene é classicamente implicado?",
o:["HLA-DQ2","NOD2/CARD15","BTK","AIRE","FOXP3"],c:1,
e:"<b>Doença de Crohn</b>: NOD2/CARD15 (reconhecimento bacteriano), ATG16L1 e IRGM (autofagia). Resposta Th1/Th17 contra microbiota; transmural; granulomas não caseosos."},
{id:"i33",a:"imuno",t:["i-dai"],s:"No LES, os níveis séricos de C3 e C4 durante a atividade da doença tendem a estar:",
o:["Elevados, por produção hepática aumentada","Reduzidos, por consumo na ativação do complemento pelos imunocomplexos","Normais sempre","Elevados apenas o C4","Sem relação com a atividade"],c:1,
e:"Imunocomplexos ativam complemento → <b>consumo → C3 e C4 baixos</b>; C5a atrai neutrófilos. Bom marcador de atividade (sobretudo nefrite)."},
{id:"i34",a:"imuno",t:["i-dai"],s:"Qual citocina, produzida principalmente por células dendríticas plasmocitoides, perpetua a ativação imune no LES?",
o:["IL-4","IFN tipo I (IFN-α)","IL-10","TGF-β","IL-13"],c:1,
e:"<b>IFN-α</b> (tipo I) das pDC perpetua a ativação; além disso Th1/Th17 (IFN-γ, IL-17) e plasmócitos de longa vida."},
{id:"i35",a:"imuno",t:["i-anemias"],s:"Mulher, 32 anos, menorragia, Hb 9,0 g/dL, VCM 68 fL, ferritina 6 ng/mL, ferro sérico baixo, CTLF elevada, saturação 6%, reticulócitos baixos. Qual o diagnóstico e por que a CTLF está alta?",
o:["Anemia de doença crônica; transferrina bloqueada","Anemia ferropriva; aumento da transferrina como 'mecanismo de desespero' para captar ferro","Talassemia; excesso de transferrina","Anemia megaloblástica; hemólise","Anemia sideroblástica; excesso de ferro"],c:1,
e:"<b>Ferropriva</b>: ferritina (estoque) é o primeiro a cair; transferrina vazia (sat ↓) e aumentada (CTLF ↑) para capturar ferro. Microcítica, retic ↓ (falta matéria-prima). Causa: perda crônica."},
{id:"i36",a:"imuno",t:["i-anemias"],s:"Homem vegano estrito há 8 anos, com Hb 8,5, VCM 118 fL, neutrófilos hipersegmentados, parestesias. Reticulócitos baixos. Diagnóstico:",
o:["Anemia ferropriva","Anemia megaloblástica por deficiência de B12","Anemia falciforme","Talassemia beta","Anemia hemolítica autoimune"],c:1,
e:"<b>Megaloblástica</b>: VCM &gt; 100, <b>neutrófilos hipersegmentados</b>; B12 só vem de alimento animal. DNA não duplica → assincronia → célula grande; medula hipoprodutiva (retic ↓)."},
{id:"i37",a:"imuno",t:["i-anemias"],s:"Criança afrodescendente de 2 anos com crises de dor nas mãos e pés, icterícia leve e anemia. Laboratório: Hb 7,5, VCM normal, reticulócitos aumentados, bilirrubina indireta e LDH elevadas. Qual exame confirma o diagnóstico?",
o:["Ferritina","Eletroforese de hemoglobina","Dosagem de B12","Mielograma","Teste de Coombs"],c:1,
e:"<b>Anemia falciforme</b> (hemólise: retic ↑, BI ↑, LDH ↑; vaso-oclusão → dor). Confirmação: <b>eletroforese de Hb</b> (banda HbS). Triagem: teste do pezinho."},
{id:"i38",a:"imuno",t:["i-anemias"],s:"Por que a anemia falciforme só se manifesta por volta dos 6 meses de vida?",
o:["Porque a IgG materna protege a hemácia","Porque até então predomina a HbF (α2γ2), e a mutação está na cadeia β","Porque a medula fetal não produz hemácias","Porque o baço ainda não funciona","Porque a HbS só é produzida na puberdade"],c:1,
e:"A mutação (Glu→Val) está na <b>β-globina</b>. O feto/lactente produz <b>HbF (γ)</b>; por volta dos 6 meses a γ é silenciada e a β ativada → HbS aparece."},
{id:"i39",a:"imuno",t:["i-anemias"],s:"Sobre o traço falcêmico (HbAS), assinale a correta:",
o:["Causa anemia grave com Hb de 6–9 g/dL","Cerca de 50% HbA1 e 50% HbS; geralmente sem anemia; falcização em massa apenas em hipóxia extrema (alta altitude)","É herdado de ambos os pais","Causa autoesplenectomia na infância","Os drepanócitos estão sempre presentes no esfregaço"],c:1,
e:"Traço (heterozigoto): ~50/50, vida normal; exceção: ambiente de baixa O₂ (altitude) → crise."},
{id:"i40",a:"imuno",t:["i-anemias"],s:"O reticulócito é útil no raciocínio da anemia porque:",
o:["Mede o estoque de ferro","Indica a atividade da medula: alto em hemólise/hemorragia aguda, baixo em falta de produção","É marcador de inflamação","Mede a B12","Indica o tamanho da hemácia"],c:1,
e:"Reticulócito = célula anterior à hemácia; <b>↑ = medula produtiva</b> (hemólise, sangramento agudo); <b>↓ = hipoprodução</b> (falta de ferro, B12, folato, EPO, medula invadida)."},
{id:"i41",a:"imuno",t:["i-anemias"],s:"Na eletroforese de hemoglobina de um adulto normal, espera-se:",
o:["HbF ~98%","HbA1 (α2β2) ~98% e HbA2 (α2δ2) ~2%","HbS ~50%","HbA2 ~50%","Apenas HbA2"],c:1,
e:"Adulto: <b>HbA1 ~98%</b>, HbA2 ~2%, HbF residual. Talassemia beta pode aumentar HbF e HbA2."},
/* ======================= INTEGRADAS ======================= */
{id:"x1",a:"int",t:["p-les","p-trombose","i-dai"],s:"Mulher de 30 anos com LES apresenta três abortos espontâneos e TVP recente. Exames: TTPa prolongado que não corrige com plasma normal e anticorpos anti-β2-glicoproteína I positivos. Qual a interpretação correta?",
o:["Há tendência hemorrágica pelo TTPa prolongado; evitar anticoagulação","Síndrome do anticorpo antifosfolipídio: o anticoagulante lúpico prolonga o TTPa in vitro, mas é pró-trombótico in vivo","Hemofilia adquirida","Deficiência de vitamina K","CID crônica"],c:1,
e:"<b>SAF</b>: anticorpos contra complexos com <b>β2-GPI</b> ativam endotélio, plaquetas, complemento → trombose arterial/venosa + perdas fetais. Paradoxo do <b>anticoagulante lúpico</b>: prolonga TTPa no laboratório, trombose no corpo."},
{id:"x2",a:"int",t:["i-transplante","p-infarto","p-trombose"],s:"Receptor de transplante renal com três gestações prévias recebe rim ABO compatível sem crossmatch adequado. Minutos após a reperfusão o rim escurece. Na patologia do enxerto removido espera-se:",
o:["Arteriosclerose do enxerto com fibrose","Trombose maciça dos vasos e necrose hemorrágica, com neutrófilos e complemento no endotélio","Endotelialite com infiltrado de CD8","Granulomas não caseosos","Necrose tubular aguda isolada"],c:1,
e:"Gestações → sensibilização a HLA paterno → <b>anticorpos pré-formados</b> → hiperaguda: complemento + coagulação → <b>trombose maciça e necrose hemorrágica</b> (o 'enxerto vira coágulo')."},
{id:"x3",a:"int",t:["p-choque","p-embolia","i-idinata"],s:"Homem com pneumonia grave evolui com hipotensão refratária, pele quente, petéquias, sangramento nos acessos venosos e oligúria. Qual sequência imunopatológica explica o quadro?",
o:["IgE → mastócitos → histamina","PAMPs (LPS) → TLR → NF-κB → TNF, IL-1 → vasodilatação, lesão endotelial, ativação do fator tecidual e ↓ trombomodulina → CID","Imunocomplexos → vasculite → púrpura","Perda do tônus simpático → bradicardia","Anticorpos anti-PF4 → trombose"],c:1,
e:"<b>Choque séptico</b> com <b>CID</b>: imunidade inata (TLR, NF-κB, TNF, IL-1, HMGB1, complemento) → endotélio perde propriedades anticoagulantes → microtrombos que consomem plaquetas/fatores → sangramento. Rim (NTA) costuma falhar primeiro."},
{id:"x4",a:"int",t:["p-choque","i-idinata"],s:"Minutos após receber penicilina, paciente apresenta urticária generalizada, sibilância, edema de lábios e PA 70/40 com taquicardia. Qual a classificação do choque e o mecanismo imune?",
o:["Choque hipovolêmico; tipo III","Choque distributivo anafilático; hipersensibilidade tipo I (IgE → mastócitos/basófilos → histamina)","Angioedema hereditário; deficiência de C1-INH","Choque neurogênico; perda simpática","Choque cardiogênico; tipo II"],c:1,
e:"<b>Anafilaxia</b> = tipo I: IgE em mastócitos/basófilos + alérgeno → desgranulação → histamina → dilatação venular, ↑ permeabilidade, edema, broncoconstrição. Urticária e broncoespasmo distinguem do AEH."},
{id:"x5",a:"int",t:["x-tireoide","p-trombose","p-embolia","p-infarto"],s:"Mulher de 38 anos com exoftalmia, bócio difuso com sopro e perda de peso apresenta subitamente hemiparesia direita. ECG: fibrilação atrial. Qual a cadeia de eventos mais provável?",
o:["Hashitoxicose → vasculite cerebral","Graves (TSI estimulando o receptor de TSH) → hipertireoidismo → FA → estase atrial → trombo → embolia cerebral → infarto com necrose liquefativa","Graves → hipercoagulabilidade por fator V de Leiden","Hashimoto → hipotireoidismo → aterosclerose","Embolia gordurosa"],c:1,
e:"Integração: <b>TSI (tipo II estimulador)</b> → hipertireoidismo → <b>fibrilação atrial</b> (estase = Virchow) → trombo no átrio esquerdo → <b>embolia sistêmica</b> → infarto cerebral (<b>necrose liquefativa</b>, gliose)."},
{id:"x6",a:"int",t:["i-anemias","p-trombose","i-dai"],s:"Paciente com anemia perniciosa (autoanticorpos contra fator intrínseco) não tratada apresenta TVP espontânea. Qual elo fisiopatológico liga as duas condições?",
o:["Trombocitose reativa","Deficiência de B12 → hiper-homocisteinemia → estresse oxidativo, inativação de NO, inibição da trombomodulina e da fibrinólise","Anticorpos antifosfolipídio cruzados","Excesso de ferro","Policitemia"],c:1,
e:"B12 (e folato, B6) é cofator do metabolismo da homocisteína. Falta → <b>homocisteína ↑</b> → trombofilia (hereditária ou adquirida). A anemia perniciosa é <b>autoimune</b>; o quadro hematológico é megaloblástico."},
{id:"x7",a:"int",t:["i-anemias","p-infarto","i-idinata"],s:"Jovem com anemia falciforme apresenta pneumonia pneumocócica grave e, no passado, episódio de infarto esplênico. Qual alternativa integra corretamente o caso?",
o:["Infartos esplênicos repetidos levam a autoesplenectomia, com perda da filtração e maior suscetibilidade a bactérias encapsuladas","A falcização ocorre na oxigenação e protege o baço","O infarto esplênico é vermelho por circulação dupla","A susceptibilidade a pneumococo deve-se a deficiência de C9","A pneumonia aumenta HbF e melhora a anemia"],c:0,
e:"Vaso-oclusão → infartos (baço tem circulação terminal → infarto branco) → <b>autoesplenectomia</b> → menor clearance de <b>encapsulados</b> (pneumococo, Hib, meningococo)."},
{id:"x8",a:"int",t:["i-dai","i-idadapt","i-anemias"],s:"Menina de 9 anos com diarreia crônica, baixa estatura e anemia microcítica refratária a ferro oral. Anti-tTG IgA negativo, mas biópsia duodenal com atrofia vilositária e linfocitose intraepitelial. Qual a explicação mais provável para a sorologia negativa?",
o:["Erro de biópsia","Deficiência seletiva de IgA associada, tornando a sorologia IgA falso-negativa","Doença de Crohn","SCID","Uso de glúten em excesso"],c:1,
e:"Celíaca e <b>deficiência de IgA</b> se associam; sem IgA, o anti-tTG <b>IgA</b> dá falso-negativo. A anemia ferropriva vem da <b>má absorção</b> (duodeno) → ferro oral não funciona."},
{id:"x9",a:"int",t:["p-infarto","p-choque","p-trombose","p-edema"],s:"Homem com IAM extenso de parede anterior evolui com choque cardiogênico. Sobrevive, mas no 10º dia apresenta dor lombar súbita e hematúria. Qual a explicação?",
o:["Pielonefrite","Trombo mural no VE (discinesia + lesão endocárdica) → embolia sistêmica → infarto renal branco","Necrose tubular aguda","Litíase renal","Infarto renal hemorrágico por torção"],c:1,
e:"IAM → contração <b>discinética</b> + lesão endocárdica → <b>trombo mural</b> → embolia para cérebro, <b>rim</b>, baço → infarto <b>branco</b> (rim: circulação terminal)."},
{id:"x10",a:"int",t:["p-infarto","i-dai","p-autoimune"],s:"No reparo de um infarto do miocárdio, a substituição do tecido necrótico por cicatriz fibrosa depende principalmente de:",
o:["Macrófagos M1 produzindo IFN-γ","Macrófagos M2 produzindo TGF-β, que ativa fibroblastos a depositar colágeno","Linfócitos B produzindo anticorpos","Mastócitos liberando histamina","Neutrófilos produzindo colágeno"],c:1,
e:"Tecido de granulação: <b>M2 → TGF-β → fibroblastos → colágeno</b> → cicatriz. É o mesmo eixo que, desregulado, causa fibrose na <b>esclerodermia</b> (Th2 → M2 → TGF-β)."},
{id:"x11",a:"int",t:["p-edema","i-idinata"],s:"Paciente cirrótico tem infecções bacterianas frequentes. Além da ascite como meio de cultura, qual fator imunológico contribui?",
o:["Excesso de complemento","Imunodeficiência secundária: o fígado doente produz menos proteínas do complemento (e albumina), e a ascite é pobre em opsoninas","Deficiência de BTK adquirida","Excesso de IgE","Hiperatividade de Treg induzida por bilirrubina"],c:1,
e:"Doença hepática é causa de <b>IDS</b>: o fígado produz complemento. Somado à ascite (transudato sem Ig/complemento) e translocação bacteriana → <b>PBE</b>."},
{id:"x12",a:"int",t:["i-idinata","p-autoimune","p-les"],s:"Criança com deficiência congênita de C2 desenvolve eritema malar fotossensível, artrite e nefrite. A melhor explicação é:",
o:["Coincidência sem relação","Deficiência de componentes iniciais da via clássica prejudica a remoção de imunocomplexos e células apoptóticas, predispondo ao LES","Excesso de MAC lesando rins","Deficiência de C2 causa anafilaxia","C2 é necessário para a formação de anti-dsDNA"],c:1,
e:"Deficiência de <b>C1q, C2, C4</b> → clearance ruim de imunocomplexos e apoptóticos → antígenos nucleares expostos → <b>LES</b> (tipo III; alça de arame, asa de borboleta)."},
{id:"x13",a:"int",t:["p-sjogren-esclero","i-idadapt","p-autoimune"],s:"Uma paciente com síndrome de Sjögren e outra com CVID compartilham qual risco neoplásico?",
o:["Carcinoma hepatocelular","Linfoma (estimulação/desregulação crônica de linfócitos B)","Melanoma","Adenocarcinoma de próstata","Feocromocitoma"],c:1,
e:"Sjögren: risco até 40× de <b>linfoma B</b>. CVID: linfoproliferação, <b>linfoma</b> e câncer gástrico. Ambos têm desregulação de B."},
{id:"x14",a:"int",t:["i-transplante","i-idinata"],s:"Transplantado cardíaco em uso de tacrolimus, micofenolato e corticoide apresenta pneumonia por Pneumocystis e lesão cutânea por HPV de crescimento rápido. Qual conceito explica?",
o:["Rejeição crônica","Imunodeficiência secundária por imunossupressores, com infecções oportunistas e mais neoplasias (vírus oncogênicos, falta de imunovigilância)","DECH","Imunodeficiência primária","Deficiência de C3"],c:1,
e:"Imunossupressão excessiva → <b>IDS</b>: oportunistas e neoplasias. Pouca imunossupressão → rejeição. Equilíbrio fino."},
{id:"x15",a:"int",t:["p-ar","i-anemias","i-dai"],s:"Mulher com artrite reumatoide ativa tem Hb 10,2, VCM 84, ferro sérico baixo, CTLF baixa, ferritina elevada. Qual o tipo de anemia?",
o:["Ferropriva","Anemia de doença crônica (inflamação altera distribuição e uso do ferro)","Megaloblástica","Falciforme","Sideroblástica com excesso de ferro"],c:1,
e:"<b>Doença crônica</b>: ferro 'preso' nos estoques pela inflamação (TNF, IL-6). Ferritina normal/↑ (também reagente de fase aguda), <b>CTLF ↓</b> — diferente da ferropriva (ferritina ↓, CTLF ↑)."},
{id:"x16",a:"int",t:["p-edema","p-trombose","i-idadapt"],s:"Criança com síndrome nefrótica grave apresenta anasarca, peritonite pneumocócica e trombose de veia renal. Qual alternativa integra corretamente?",
o:["Edema por ↑ permeabilidade; infecções por excesso de IgG; trombose por plaquetopenia","Edema por ↓ oncótica (perda de albumina); infecções por perda urinária de imunoglobulinas/fatores; trombose por hipercoagulabilidade (perda de antitrombina)","Edema linfático; infecções por DGC; trombose por estase isolada","Edema por ICC; infecções por asplenia; trombose por TIH","Nenhuma relação entre os achados"],c:1,
e:"Nefrótica: perde <b>albumina</b> (↓ oncótica → anasarca), perde Ig (IDS) e anticoagulantes como <b>antitrombina III</b> (hipercoagulabilidade; listada como fator de risco de trombose)."},
{id:"x17",a:"int",t:["p-sjogren-esclero","p-edema"],s:"Paciente com esclerodermia difusa e anti-Scl-70 positivo desenvolve cefaleia, PA 220/130 e insuficiência renal rápida. Qual a lesão renal esperada?",
o:["Alça de arame glomerular","Hiperplasia concêntrica da íntima das artérias interlobulares (casca de cebola) sem alteração glomerular específica","Glomerulonefrite crescêntica por anti-MBG","Necrose tubular aguda por choque","Nefrite intersticial por fármacos"],c:1,
e:"<b>Crise renal esclerodérmica</b> (~20%): vasculopatia obliterativa em <b>casca de cebola</b> nas interlobulares → isquemia → hipertensão maligna. <b>Sem alteração glomerular específica</b>."},
{id:"x18",a:"int",t:["i-idinata","p-infarto","p-autoimune"],s:"Granulomas aparecem em vários contextos do curso. Em qual alternativa a associação está ERRADA?",
o:["DGC: granulomas por falha de eliminar micróbios dentro do fagócito","Crohn: granulomas não caseosos","Nódulo reumatoide: aspecto de granuloma necrosante com macrófagos em paliçada","Deficiência de IL-12R: dificuldade de formar granulomas eficientes contra micobactérias","LAD I: granulomas com pus abundante"],c:4,
e:"LAD I caracteriza-se por <b>ausência de pus</b> (leucócito não sai do vaso). As demais associações estão corretas."},
{id:"x19",a:"int",t:["p-trombose","i-idinata","p-hemorragia"],s:"Criança com infecções bacterianas recorrentes, cicatrização ruim e sangramentos mucosos frequentes; leucócitos elevados e plaquetas em número normal, porém sem agregação. O diagnóstico é:",
o:["LAD I","LAD III (defeito de ativação de integrinas em leucócitos e plaquetas)","Trombastenia isolada","DGC","Hemofilia A"],c:1,
e:"LAD III: integrinas não são ativadas — leucócitos não aderem (infecções, sem pus) e plaquetas não agregam via <b>GpIIb/IIIa</b> (hemostasia primária) → sangramento."},
{id:"x20",a:"int",t:["x-tireoide"],s:"Mulher de 45 anos com bócio indolor e firme, cansaço, ganho de peso. TSH 18 mU/L, T4 livre baixo, anti-TPO muito elevado. A histologia esperada e o principal mecanismo são:",
o:["Hiperplasia papilar com coloide escasso — anticorpo estimulador","Infiltrado linfoplasmocitário com centros germinativos, folículos atróficos com células de Hürthle — tipo IV (T CD4 Th1/CD8) com participação de anticorpos (tipo II)","Granulomas com células gigantes — tireoidite subaguda","Fibrose que ultrapassa a cápsula — Riedel","Necrose caseosa — tuberculose"],c:1,
e:"<b>Hashimoto</b>: dano principal celular (tipo IV: CD8, Th1 → IFN-γ → macrófagos) + anti-TPO/anti-Tg (tipo II, ADCC). Hürthle = metaplasia oxifílica; fibrose não ultrapassa a cápsula."},
{id:"x21",a:"int",t:["x-tireoide"],s:"Paciente com Hashimoto recém-diagnosticado apresenta inicialmente palpitações, T4 livre elevado, TSH suprimido e captação de iodo radioativo REDUZIDA. Explicação:",
o:["Doença de Graves concomitante obrigatória","Hashitoxicose: destruição folicular libera hormônio pré-formado (não há síntese aumentada)","Tumor produtor de TSH","Excesso de iodo dietético apenas","Efeito do anti-TPO estimulando a glândula"],c:1,
e:"<b>Hashitoxicose</b>: ruptura de folículos → liberação de hormônio armazenado → T4/T3 ↑, TSH ↓, mas <b>captação ↓</b> (glândula não está sintetizando mais). No Graves a captação é ↑."},
{id:"x22",a:"int",t:["x-tireoide"],s:"Por que, na doença de Graves, o hipertireoidismo persiste mesmo com TSH suprimido?",
o:["Porque há tumor hipofisário","Porque o TSI (IgG) se liga ao receptor de TSH e o ativa independentemente do eixo, não sofrendo feedback negativo","Porque o anti-TPO estimula a síntese","Porque o iodo induz autonomia","Porque há deficiência de Treg tireoidiana"],c:1,
e:"O <b>TSI</b> é o 'impostor': ativa o receptor (adenilato ciclase) sem passar pelo eixo hipotálamo-hipófise → feedback reduz TSH, mas não o anticorpo. Tipo II estimulador."},
{id:"x23",a:"int",t:["x-tireoide"],s:"A exoftalmia da doença de Graves NÃO se deve a:",
o:["Infiltração retro-orbitária por linfócitos T","Edema e inflamação dos músculos extraoculares","Acúmulo de glicosaminoglicanos hidrofílicos","Aumento de adipócitos","Excesso de T4 agindo diretamente sobre a gordura orbitária, revertendo totalmente com o controle do hipertireoidismo"],c:4,
e:"A oftalmopatia é <b>autoimune</b> (receptor de TSH nos fibroblastos orbitários, reação cruzada, GAG) e pode <b>persistir ou progredir</b> mesmo com o hipertireoidismo tratado."},
{id:"x24",a:"int",t:["p-embolia","p-trombose","i-dai"],s:"Paciente com doença de Crohn ativa, internado e imobilizado, desenvolve TEP. Quais fatores da tríade de Virchow podem ser atribuídos ao quadro?",
o:["Apenas estase","Estase (imobilização) e hipercoagulabilidade/ativação endotelial pela inflamação sistêmica (↓ trombomodulina, ↓ proteína C, ↑ PAI)","Apenas turbulência","Nenhum, pois Crohn protege contra trombose","Apenas lesão endotelial por cateter"],c:1,
e:"Inflamação ativa endotélio → efeito pró-coagulante e antifibrinolítico; somado à <b>estase</b> da internação. TVP → cava → AD → VD → artéria pulmonar."},
{id:"x25",a:"int",t:["i-idadapt","i-transplante"],s:"Lactente com SCID recebe transfusão de sangue não irradiado e desenvolve exantema, diarreia e icterícia. O mecanismo é:",
o:["Rejeição hiperaguda","DECH: linfócitos T viáveis do doador não são eliminados pelo receptor imunodeficiente e atacam pele, fígado e TGI","Reação hemolítica ABO","Anafilaxia anti-IgA","Infecção por CMV"],c:1,
e:"Receptor sem T não rejeita os T do doador → estes reconhecem aloantígenos do hospedeiro → <b>DECH</b> (pele, fígado, TGI). Por isso hemocomponentes para SCID são irradiados."},
{id:"x26",a:"int",t:["p-hemorragia","i-anemias"],s:"Homem de 60 anos com sangue oculto nas fezes por adenocarcinoma de cólon há meses. Qual anemia e qual o 'destino do ferro' explica?",
o:["Megaloblástica; ferro reciclado","Ferropriva microcítica; o sangue perdido para o meio externo leva o ferro embora","Hemolítica; ferro acumulado no baço","Doença crônica exclusivamente; ferro aumentado","Falciforme"],c:1,
e:"Gravidade da hemorragia — fator 3: <b>destino do ferro</b>. Perda externa crônica → <b>ferropriva</b>. Sangue retido nos tecidos (hematoma) → ferro reciclado por macrófagos."},
{id:"x27",a:"int",t:["p-autoimune","i-dai","i-idadapt"],s:"Mutações em FOXP3 (síndrome IPEX) e AIRE causam autoimunidade grave porque, respectivamente:",
o:["Impedem a troca de classe e a maturação de B","Impedem a formação de Treg (tolerância periférica) e a expressão de antígenos teciduais no timo (tolerância central)","Causam deficiência de C1q e C4","Bloqueiam a calcineurina","Impedem a apoptose de neutrófilos"],c:1,
e:"<b>FOXP3</b> = fator de transcrição das <b>Treg</b>. <b>AIRE</b> = expressão de antígenos periféricos no timo para seleção negativa. FAS = apoptose (periférica)."},
{id:"x28",a:"int",t:["p-choque","p-hemorragia","i-anemias"],s:"Vítima de acidente com fratura de bacia e perda estimada de 30% do volume sanguíneo. Na primeira hora, a Hb ainda está quase normal. Qual alternativa é correta?",
o:["A Hb normal exclui hemorragia importante","Na perda aguda, a Hb inicialmente pode estar normal (perde-se sangue total); com reposição volêmica e redistribuição cai; dias depois os reticulócitos aumentam","Os reticulócitos aumentam em minutos","Trata-se de anemia microcítica imediata","O choque é distributivo"],c:1,
e:"Hemorragia aguda: perda de sangue total, Hb cai depois (hemodiluição). Choque <b>hipovolêmico</b> (&gt;20%). Medula responde com <b>reticulocitose</b> em dias (normocítica)."},
{id:"x29",a:"int",t:["i-transplante","p-autoimune"],s:"Qual paralelo entre tolerância periférica e imunossupressão está correto?",
o:["Belatacepte imita a anergia por bloquear a coestimulação B7–CD28","Ciclosporina imita a seleção negativa tímica","Sirolimo induz edição de receptor","Corticoides induzem expressão de AIRE","Anti-CD25 aumenta a função de Treg obrigatoriamente"],c:0,
e:"Sinal 1 sem sinal 2 → <b>anergia</b>. Belatacepte (CTLA4-Ig) bloqueia B7 e reproduz esse mecanismo — inclusive CTLA-4 é gene de suscetibilidade a autoimunidade."},
{id:"x30",a:"int",t:["p-autoimune","i-dai"],s:"Associe a doença ao mecanismo de hipersensibilidade predominante:",
o:["LES – IV; Graves – III; Hashimoto – I","LES – III; Graves – II; Miastenia – II; Hashimoto – IV (+II); Esclerodermia – IV (Th2)","LES – II; Miastenia – III; DM1 – I","Sjögren – III; AR – I; Celíaca – II","Todas são tipo III"],c:1,
e:"LES <b>III</b>; Graves <b>II</b> (estimulador); Miastenia <b>II</b> (bloqueador); Hashimoto <b>IV</b> + II; AR <b>III + IV</b>; Sjögren <b>IV Th1</b>; Esclerodermia <b>IV Th2</b>; DM1 IV (CD8)."},
{id:"x31",a:"int",t:["p-hemorragia","i-idadapt"],s:"Menino com eczema, plaquetas pequenas e baixas (petéquias) e infecções de repetição. Independentemente do nome da síndrome, a petéquia indica falha de qual etapa e qual a lesão de pele característica?",
o:["Hemostasia secundária; hematoma","Hemostasia primária (plaquetas); petéquias de 1–2 mm","Fibrinólise; equimose","Vasoconstrição; púrpura palpável","Contrarregulação; hemartrose"],c:1,
e:"Plaquetopenia = falha da <b>hemostasia primária</b> → <b>petéquias</b> e sangramento mucoso imediato. (Ponte entre imunodeficiência e hemostasia.)"},
{id:"x32",a:"int",t:["p-choque","p-infarto"],s:"Qual a diferença conceitual entre choque e infarto, segundo a aula?",
o:["São sinônimos","Infarto é necrose isquêmica localizada por obstrução vascular; choque é hipoperfusão sistêmica com hipóxia celular generalizada","Choque é sempre consequência de infarto renal","Infarto é sempre séptico","Choque é localizado e infarto sistêmico"],c:1,
e:"Choque = <b>sistêmico</b> (hipoperfusão global). Infarto = <b>localizado</b>. O IAM pode causar choque cardiogênico, e o choque pode causar infartos (redistribuição do fluxo é causa funcional de isquemia)."}
];
